 void submit(const std::vector<uint32_t>&code){unsigned pos=0;while(pos<code.size()){auto x=tick(code[pos],pos+1<code.size()?code[pos+1]:0,true,pos+1<code.size());require(!x[1]||x[0],"non-prefix admission");pos+=x[0]+x[1];}}
