 void boundTest(bool overlapping){scenario=overlapping?2:1;overlap=overlapping;setup();virtualSetup();constant(25,0x336699cc);run({divide(28,25,26),store(4,0,28,2),load(10,4,overlap?2:4,overlap?1:2)});if(overlap){require(writeQueries&&proofs,"overlap contrast did not obtain write proof");require(!binds&&!boundStarts&&!creditConsumes&&!frozenRequests,"overlapping younger load incorrectly used bypass/binding");}else{require(writeQueries&&proofs&&binds&&boundStarts&&frozenRequests&&creditConsumes&&unreadyBindings,"positive bound lifecycle witness missing");require(queryCycle<proofCycle&&proofCycle<=bindCycle&&bindCycle<storeCycle,"bound lifecycle order missing");}}
